import { eventFacts, activityRange } from './facts.js';
import { decimatorPlayer } from './games.js';
import { ticketCounts } from './tickets.js';
import { farFutureQueue } from './positions.js';
import { playerAddress, uint, ZERO_ADDRESS } from './state.js';
import { checkAbort } from './client.js';

export async function decimatorRounds(s, player, signal) {
  const events = await eventFacts(s, ['DecBurnRecorded'], { contract: 'GAME', player, signal });
  const levels = [...new Set(events.map(e=>Number(e.args.lvl)))]; const rows = [];
  for (let i=0;i<levels.length;i+=12) {
    checkAbort(signal); rows.push(...await Promise.all(levels.slice(i,i+12).map(level=>decimatorPlayer(s,level,player))));
  }
  return rows;
}
export async function decimatorClaims(s, player, signal) {
  return (await decimatorRounds(s,player,signal)).filter(row=>row.roundStatus==='closed' && BigInt(row.ethAmount)+BigInt(row.lootboxAmount)>0n);
}
export async function playerHoldings(s, player, signal) {
  const active = Number(await s.call('GAME_LENS','activeTicketLevelOf',[s.client.address('GAME')]));
  const [near, far] = await Promise.all([ticketCounts(s,player,Array.from({length:6},(_,i)=>active+i),{signal}), farFutureQueue(s,player,{signal})]);
  return [...near,...far.rows].filter(row=>row.entryCount>0);
}
export async function extendPlayer(s, result, q, signal) {
  if (q.has('pending')) { const { pendingBets } = await import('./pending.js'); result.degenerette.pendingBets = await pendingBets(s,result.player,signal); }
  if (q.has('inventory')) result.tickets = await playerHoldings(s,result.player,signal);
  if (q.has('claims')) {
    const rows = await decimatorClaims(s,result.player,signal);
    result.decimatorClaims = rows; result.decimator.claimablePerLevel = rows;
  }
  return result;
}
async function affiliateClaim(s, player) {
  const level = Number(await s.field('GAME','level')); if (!level) return 0n;
  const [claimed, score, total, deity, allocation, pool] = await Promise.all([
    s.field('GAME','affiliateDgnrsClaimedBy',level,player),s.call('AFFILIATE','affiliateScore',[level,player]),
    s.call('AFFILIATE','totalAffiliateScore',[level]),s.call('GAME','hasDeityPass',[player]),
    s.call('GAME_LENS','levelDgnrsInfo',[s.client.address('GAME'),level]),s.call('SDGNRS','poolBalance',[1]),
  ]);
  if (claimed || !total || !deity && score < 10n*10n**18n) return 0n;
  const share = allocation.allocation * score / total; return share > pool ? pool : share;
}
export async function readPlayerRoute(s, url, {signal}={}) {
  const p=url.pathname.split('/').filter(Boolean),q=url.searchParams;
  if (url.pathname==='/players/search') {
    const query=(q.get('q')??'').trim(); let address=/^0x[0-9a-f]{40}$/i.test(query)?query.toLowerCase():null;
    if(!address) {
      const {normalizePurchaseAffiliateCode}=await import('../app/affiliate.js');
      let code;try{code=normalizePurchaseAffiliateCode(query);}catch{return {query,results:[],total:0};}
      if(BigInt(code)>0n) {
        const info=await s.call('AFFILIATE','affiliateCode',[code]);
        address=info.owner.toLowerCase();
        if(address===ZERO_ADDRESS)address=BigInt(code)<(1n<<160n)?'0x'+BigInt(code).toString(16).padStart(40,'0'):null;
      }
    }
    return {query,results:address?[{address,affiliateCode:/^0x/.test(query)?null:query.toUpperCase()}]:[],total:address?1:0,searchMode:'exact-address-or-code'};
  }
  const raw = p[0]==='player'?p[1]:p[0]==='game'&&p[1]==='decimator'&&p[2]==='player'?p[3]:null;
  if (!raw) return undefined; const player=playerAddress(raw);
  if (p[0]==='game') return {player,rounds:(await decimatorRounds(s,player,signal)).map(row=>({ ...row,
    resolved:row.roundStatus==='closed',isWinner:BigInt(row.ethAmount)+BigInt(row.lootboxAmount)>0n,
    claimableEth:row.claimed?'0':row.ethAmount,claimedEthAmount:row.claimed?row.ethAmount:'0',claimedLootboxAmount:row.claimed?row.lootboxAmount:'0',
    playerSubBucket:row.subbucket,winningSubBucket:row.winningSubbucket }))};
  if (p[2]==='holdings') return {player,tickets:await playerHoldings(s,player,signal)};
  if (p[2]==='pending') {
    const [eth,flip,rows,affiliate]=await Promise.all([
      s.call('GAME','claimableWinningsOf',[player]),s.call('COINFLIP','previewClaimCoinflips',[player]),
      decimatorClaims(s,player,signal),affiliateClaim(s,player),
    ]);
    const prize=amount=>({amount:String(amount),available:true,reason:null});
    return {player,pending:{eth:prize(eth),flip:prize(flip),decimator:prize(rows.filter(row=>!row.claimed).reduce((sum,row)=>sum+BigInt(row.ethAmount),0n)),
      tickets:{amount:null,available:false,reason:'See ticket inventory.'}, affiliate:prize(affiliate),terminal:prize(0),
      vault:{amount:null,available:false,reason:'Use the vault redemption controls.'},farFutureCoin:{amount:null,available:false,reason:'Included in your Coinflip claimable balance.'}}};
  }
  if (p[2]==='referees') {
    const events=await eventFacts(s,['ReferralUpdated'],{contract:'AFFILIATE',filters:{referrer:player},signal});
    const candidates=[...new Set(events.map(e=>e.args.player))]; const referees=[];
    for(let i=0;i<candidates.length;i+=25){checkAbort(signal);const wave=await Promise.all(candidates.slice(i,i+25).map(async address=>({address,referrer:(await s.call('AFFILIATE','getReferrer',[address])).toLowerCase()})));referees.push(...wave.filter(row=>row.referrer===player).map(row=>({address:row.address,available:true,reason:null})));}
    const parent=await s.call('AFFILIATE','getReferrer',[player]);
    return {player,referredBy:parent===ZERO_ADDRESS?null:parent,referees,total:referees.length,counts:{direct:referees.length,level2:null,level3:null}};
  }
  if(p[2]==='boons') {
    const day=uint(p[3]);const range=await activityRange(s,day,signal);
    const rows=await eventFacts(s,['DeityBoonIssued','ProtocolBoonDrawAwarded','BoonConsumed','BoonDiscarded'],{contract:'GAME',player,...range,signal});
    const issued=new Map();const families={1:[1,2,3],2:[7,8,9],3:[13,14,15],5:[17,18,19]};
    for(const e of rows){const a=e.args;if(e.name==='DeityBoonIssued'&&a.recipient===player||e.name==='ProtocolBoonDrawAwarded'&&a.winner===player){issued.set(Number(a.boonType),{boonType:Number(a.boonType),slot:Number(a.slot),deity:a.deity??a.issuer,consumed:false,consumedBoostBps:null,issuedBlock:String(e.blockNumber)});}else if(e.name==='BoonConsumed'){const candidates=[...issued.values()].filter(r=>!r.consumed&&families[Number(a.boonType)]?.includes(r.boonType));const last=candidates.at(-1);if(last){last.consumed=true;last.consumedBoostBps=Number(a.boostBps);}}else if(e.name==='BoonDiscarded'&&issued.has(Number(a.boonType)))issued.get(Number(a.boonType)).consumed=true;}
    return {address:player,day,boons:[...issued.values()]};
  }
  return undefined;
}
